@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files} (Python: {self.python_files})")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("-" * 40)
        for g in self.gates:
            status_icon = "✓" if g.passed else ("✗" if g.status == FAILED else "-")
            lines.append(f"[{status_icon}] {g.name}: {g.status} ({g.method})")
            if g.detail:
                lines.append(f"    Detail: {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    blocks = {}
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i]
        # Look for start of code block
        if line.strip().startswith("```"):
            # Extract language and potential filename
            header = line.strip()[3:].strip()
            parts = header.split()
            lang = parts[0] if parts else ""
            filename = parts[1] if len(parts) > 1 else None

            # If no filename in header, try to find it in the next line or assume generic
            if not filename:
                # Check if next line looks like a filename comment or just start content
                # For simplicity, if no filename, we might skip or use a generic name
                # But spec says "path->content map", so we need a path.
                # Often agents put filename in the fence: ```python path/to/file.py
                # Or sometimes just ```python and the file is implied.
                # Let's assume if no filename, we can't map it reliably unless we guess.
                # However, standard practice in these prompts is ```python filename.py
                # If missing, we might skip or use a placeholder.
                # Let's try to see if the next line is a comment with filename?
                # For now, if no filename, we skip this block as we can't map it.
                i += 1
                continue

            # Collect content until closing ```
            content_lines = []
            i += 1
            while i < len(lines):
                if lines[i].strip().startswith("```"):
                    break
                content_lines.append(lines[i])
                i += 1

            content = "\n".join(content_lines)
            # Normalize path
            clean_path = filename.strip()
            if clean_path:
                blocks[clean_path] = content
        i += 1
    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
                source = 'workspace'
            elif isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace'
            else:
                # Try to treat as directory if it's a string path
                if isinstance(workspace, str) and os.path.isdir(workspace):
                    return self.verify_directory(workspace)

        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        if not bundle:
            # Empty workspace
            return self._empty_report(source)

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle using artifacts logic
        filtered_bundle = filter_bundle(bundle)

        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files
            for path, content in filtered_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=filtered_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        start_time = time.time()

        # Determine authored files
        if authored is None:
            # Scan directory
            all_files = []
            for root, dirs, files in os.walk(workdir):
                # Filter out generated dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.join(root, d))]
                for f in files:
                    full_path = os.path.join(root, f)
                    rel_path = os.path.relpath(full_path, workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        all_files.append(rel_path)
            authored = {p: "" for p in all_files} # Content not needed for counting, but for consistency

        authored_files_count = len(authored)
        python_files = [p for p in authored.keys() if p.endswith('.py')]
        python_files_count = len(python_files)

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, python_files))

        # 2. Build Gate
        gates.append(self._gate_build(workdir))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, python_files))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, python_files))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, python_files))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files_count,
            python_files=python_files_count,
            source=source
        )

    def _empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name="syntax", status=FAILED, method="ast.parse", detail="No Python files found"),
            GateResult(name="build", status=FAILED, method="metadata_check", detail="No packaging metadata found"),
            GateResult(name="smoke", status=FAILED, method="import_check", detail="No modules to import"),
            GateResult(name="tests", status=FAILED, method="pytest_run", detail="No test files found"),
            GateResult(name="telemetry", status=FAILED, method="ast_analysis", detail="No Python files to analyze"),
        ]
        return VerificationReport(
            gates=gates,
            score_penalty=5 * self.penalty_per_gate,
            authored_files=0,
            python_files=0,
            source=source
        )

    def _gate_syntax(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()
        if not python_files:
            return GateResult(name="syntax", status=FAILED, method="ast.parse", detail="No Python files found", duration_s=time.time()-start)

        errors = []
        for rel_path in python_files:
            full_path = os.path.join(workdir, rel_path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{rel_path}: {e}")
            except Exception as e:
                errors.append(f"{rel_path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(name="syntax", status=FAILED, method="ast.parse", detail="; ".join(errors), duration_s=duration)
        return GateResult(name="syntax", status=PASSED, method="ast.parse", detail="All files parsed successfully", duration_s=duration)

    def _gate_build(self, workdir: str) -> GateResult:
        start = time.time()
        pyproject = os.path.join(workdir, "pyproject.toml")
        setup_py = os.path.join(workdir, "setup.py")
        setup_cfg = os.path.join(workdir, "setup.cfg")

        metadata_found = False
        detail = ""

        if os.path.exists(pyproject):
            metadata_found = True
            try:
                with open(pyproject, 'rb') as f:
                    data = tomllib.load(f)
                # Check for required tables
                if not any(k in data for k in ['project', 'build-system', 'tool']):
                    return GateResult(name="build", status=FAILED, method="tomllib", detail="pyproject.toml missing required tables", duration_s=time.time()-start)
            except Exception as e:
                return GateResult(name="build", status=FAILED, method="tomllib", detail=f"Invalid pyproject.toml: {e}", duration_s=time.time()-start)
        elif os.path.exists(setup_py) or os.path.exists(setup_cfg):
            metadata_found = True
        else:
            return GateResult(name="build", status=FAILED, method="metadata_check", detail="No packaging metadata found", duration_s=time.time()-start)

        # Try pip install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, "-m", "pip", "--version"], check=True, capture_output=True, timeout=10)

            # Run install
            cmd = [self.python_executable, "-m", "pip", "install", "-e", ".", "--no-deps", "--no-build-isolation"]
            result = subprocess.run(cmd, cwd=workdir, capture_output=True, text=True, timeout=self.timeout_s)

            duration = time.time() - start
            if result.returncode != 0:
                return GateResult(name="build", status=FAILED, method="pip_install", detail=f"pip install failed: {result.stderr}", duration_s=duration)
            return GateResult(name="build", status=PASSED, method="pip_install", detail="Package installed successfully", duration_s=duration)
        except FileNotFoundError:
            return GateResult(name="build", status=SKIPPED, method="pip_install", detail="pip not available", duration_s=time.time()-start)
        except subprocess.TimeoutExpired:
            return GateResult(name="build", status=FAILED, method="pip_install", detail="pip install timed out", duration_s=time.time()-start)
        except Exception as e:
            return GateResult(name="build", status=FAILED, method="pip_install", detail=f"Error during install: {e}", duration_s=time.time()-start)

    def _gate_smoke(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()
        if not python_files:
            return GateResult(name="smoke", status=FAILED, method="import_check", detail="No modules to import", duration_s=time.time()-start)

        # Filter out test files
        non_test_modules = [p for p in python_files if "test" not in os.path.basename(p).lower()]

        if not non_test_modules:
            return GateResult(name="smoke", status=FAILED, method="import_check", detail="No non-test modules found", duration_s=time.time()-start)

        # Prepare PYTHONPATH
        env = os.environ.copy()
        src_dir = os.path.join(workdir, "src")
        python_path = f"{workdir}:{src_dir}"
        if "PYTHONPATH" in env:
            python_path = f"{python_path}:{env['PYTHONPATH']}"
        env["PYTHONPATH"] = python_path

        # Try importing each module
        import_errors = []
        module_not_found_errors = []

        for rel_path in non_test_modules:
            # Convert path to module name
            # e.g. src/foo/bar.py -> foo.bar
            # e.g. foo/bar.py -> foo.bar
            parts = rel_path.split(os.sep)
            if parts[0] == "src":
                parts = parts[1:]
            if parts[-1].endswith(".py"):
                parts[-1] = parts[-1][:-3]
            module_name = ".".join(parts)

            # Run subprocess to import
            code = f"import {module_name}"
            try:
                result = subprocess.run(
                    [self.python_executable, "-c", code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                if result.returncode != 0:
                    stderr = result.stderr
                    if "ModuleNotFoundError" in stderr:
                        module_not_found_errors.append(f"{module_name}: {stderr.strip()}")
                    else:
                        import_errors.append(f"{module_name}: {stderr.strip()}")
            except subprocess.TimeoutExpired:
                import_errors.append(f"{module_name}: Timeout")
            except Exception as e:
                import_errors.append(f"{module_name}: {e}")

        duration = time.time() - start

        if import_errors:
            return GateResult(name="smoke", status=FAILED, method="import_check", detail="; ".join(import_errors), duration_s=duration)

        if module_not_found_errors:
            return GateResult(name="smoke", status=SKIPPED, method="import_check", detail="Missing third-party dependencies", duration_s=duration)

        return GateResult(name="smoke", status=PASSED, method="import_check", detail="All modules imported successfully", duration_s=duration)

    def _gate_tests(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()

        # Find test files
        test_files = [p for p in python_files if "test" in os.path.basename(p).lower()]

        if not test_files:
            return GateResult(name="tests", status=FAILED, method="pytest_run", detail="No test files found", duration_s=time.time()-start)

        # Prepare PYTHONPATH
        env = os.environ.copy()
        src_dir = os.path.join(workdir, "src")
        python_path = f"{workdir}:{src_dir}"
        if "PYTHONPATH" in env:
            python_path = f"{python_path}:{env['PYTHONPATH']}"
        env["PYTHONPATH"] = python_path

        # Check if pytest is available
        try:
            subprocess.run([self.python_executable, "-m", "pytest", "--version"], check=True, capture_output=True, timeout=10)
            use_pytest = True
        except Exception:
            use_pytest = False

        if use_pytest:
            # Run pytest
            cmd = [self.python_executable, "-m", "pytest", "-v"]
            try:
                result = subprocess.run(cmd, cwd=workdir, env=env, capture_output=True, text=True, timeout=self.timeout_s)
                duration = time.time() - start
                if result.returncode == 0:
                    return GateResult(name="tests", status=PASSED, method="pytest_run", detail="All tests passed", duration_s=duration)
                else:
                    # Check if failure is due to ModuleNotFoundError
                    if "ModuleNotFoundError" in result.stderr or "ModuleNotFoundError" in result.stdout:
                        return GateResult(name="tests", status=SKIPPED, method="pytest_run", detail="Missing dependencies for tests", duration_s=duration)
                    return GateResult(name="tests", status=FAILED, method="pytest_run", detail=f"Tests failed: {result.stderr}", duration_s=duration)
            except subprocess.TimeoutExpired:
                return GateResult(name="tests", status=FAILED, method="pytest_run", detail="Tests timed out", duration_s=time.time()-start)
            except Exception as e:
                return GateResult(name="tests", status=FAILED, method="pytest_run", detail=f"Error running tests: {e}", duration_s=time.time()-start)
        else:
            # Stdlib fallback
            # We need to run a script that imports test files and runs tests
            # This is complex to do in a single subprocess call for multiple files
            # Let's try to run unittest discover first, but it misses bare functions.
            # The spec says: "run a stdlib fallback subprocess that imports each test file and collects/executes BOTH bare def test_*() functions AND unittest.TestCase subclasses"

            # We'll create a temporary runner script
            runner_code = """
import sys
import os
import unittest
import importlib.util

def run_tests(test_files):
    loader = unittest.TestLoader()
    suite = unittest.TestSuite()

    for test_file in test_files:
        try:
            spec = importlib.util.spec_from_file_location("test_module", test_file)
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)

            # Add unittest.TestCase subclasses
            for name in dir(module):
                obj = getattr(module, name)
                if isinstance(obj, type) and issubclass(obj, unittest.TestCase) and obj is not unittest.TestCase:
                    suite.addTest(loader.loadTestsFromTestCase(obj))

            # Add bare test_* functions
            for name in dir(module):
                if name.startswith("test_"):
                    obj = getattr(module, name)
                    if callable(obj) and not isinstance(obj, type):
                        # Check if it takes 0 args
                        import inspect
                        sig = inspect.signature(obj)
                        if len(sig.parameters) == 0:
                            suite.addTest(unittest.FunctionTestCase(obj))
        except ModuleNotFoundError as e:
            print(f"ModuleNotFoundError: {e}", file=sys.stderr)
            sys.exit(2) # Special exit code for skip
        except Exception as e:
            print(f"Error loading {test_file}: {e}", file=sys.stderr)
            sys.exit(1)

    runner = unittest.TextTestRunner(verbosity=2)
    result = runner.run(suite)

    if result.wasSuccessful():
        sys.exit(0)
    else:
        sys.exit(1)

if __name__ == "__main__":
    test_files = sys.argv[1:]
    run_tests(test_files)
"""
            with tempfile.NamedTemporaryFile(mode='w', suffix='.py', delete=False) as f:
                f.write(runner_code)
                runner_path = f.name

            try:
                # Pass absolute paths to test files
                abs_test_files = [os.path.join(workdir, p) for p in test_files]
                cmd = [self.python_executable, runner_path] + abs_test_files
                result = subprocess.run(cmd, cwd=workdir, env=env, capture_output=True, text=True, timeout=self.timeout_s)
                duration = time.time() - start

                if result.returncode == 0:
                    return GateResult(name="tests", status=PASSED, method="stdlib_fallback", detail="All tests passed", duration_s=duration)
                elif result.returncode == 2:
                    return GateResult(name="tests", status=SKIPPED, method="stdlib_fallback", detail="Missing dependencies for tests", duration_s=duration)
                else:
                    return GateResult(name="tests", status=FAILED, method="stdlib_fallback", detail=f"Tests failed: {result.stderr}", duration_s=duration)
            except subprocess.TimeoutExpired:
                return GateResult(name="tests", status=FAILED, method="stdlib_fallback", detail="Tests timed out", duration_s=time.time()-start)
            except Exception as e:
                return GateResult(name="tests", status=FAILED, method="stdlib_fallback", detail=f"Error running tests: {e}", duration_s=time.time()-start)
            finally:
                os.unlink(runner_path)

    def _gate_telemetry(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()
        if not python_files:
            return GateResult(name="telemetry", status=FAILED, method="ast_analysis", detail="No Python files to analyze", duration_s=time.time()-start)

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span', 'start_span', 'get_tracer', 
            'get_tracer_provider', 'set_tracer_provider', 'get_meter'
        }

        for rel_path in python_files:
            full_path = os.path.join(workdir, rel_path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                tree = ast.parse(content)

                for node in ast.walk(tree):
                    # Check for import
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                                has_import = True
                    elif isinstance(node, ast.ImportFrom):
                        if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                            has_import = True

                    # Check for calls
                    if isinstance(node, ast.Call):
                        func = node.func
                        if isinstance(func, ast.Attribute):
                            if func.attr in tracer_methods:
                                has_call = True
                        elif isinstance(func, ast.Name):
                            if func.id in tracer_methods:
                                has_call = True

            except Exception:
                continue

        duration = time.time() - start

        if has_import and has_call:
            return GateResult(name="telemetry", status=PASSED, method="ast_analysis", detail="OpenTelemetry usage detected", duration_s=duration)
        elif has_import:
            return GateResult(name="telemetry", status=FAILED, method="ast_analysis", detail="Import found but no tracer/span calls", duration_s=duration)
        else:
            return GateResult(name="telemetry", status=FAILED, method="ast_analysis", detail="No OpenTelemetry usage found", duration_s=duration)

